ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    text: ":package: Inventory check needed for order " ++ (vars.orderNumber default "(unknown)"),
    blocks: [
        {
            "type": "header",
            "text": { "type": "plain_text", "text": ":package: Inventory Check Required" }
        },
        {
            "type": "section",
            "fields": [
                { "type": "mrkdwn", "text": "*Order:*\n" ++ (vars.orderNumber default "(unknown)") },
                { "type": "mrkdwn", "text": "*Account:*\n" ++ (vars.accountName default "(no account)") },
                { "type": "mrkdwn", "text": "*Total Amount:*\nUSD " ++ (vars.totalAmount as String default "0") },
                { "type": "mrkdwn", "text": "*Lines:*\n" ++ (vars.itemCount as String default "0") }
            ]
        },
        {
            "type": "section",
            "text": { "type": "mrkdwn", "text": "*Products:*\n" ++ (vars.itemsSummary default "(none)") }
        },
        {
            "type": "section",
            "text": { "type": "mrkdwn", "text": "<" ++ (vars.orderUrl default "#") ++ "|:link: Open Order in Salesforce>" }
        },
        {
            "type": "context",
            "elements": [
                { "type": "mrkdwn", "text": ":warehouse: Reply in Salesforce: *Mark In Stock* or *Mark Out of Stock*  |  Powered by MuleSoft" }
            ]
        }
    ]
}
